const std = @import("std");
const config = @import("config.zig");

pub const Vector = struct {
    data: []f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, dims: usize) !Vector {
        const data = try allocator.alloc(f32, dims);
        @memset(data, 0);
        return Vector{
            .data = data,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Vector) void {
        self.allocator.free(self.data);
    }

    pub fn fromSlice(allocator: std.mem.Allocator, data: []const f32) !Vector {
        const copy = try allocator.alloc(f32, data.len);
        @memcpy(copy, data);
        return Vector{
            .data = copy,
            .allocator = allocator,
        };
    }

    pub fn normalize(self: *Vector) void {
        var mag_sq: f32 = 0;
        for (self.data) |x| {
            mag_sq += x * x;
        }
        if (mag_sq <= 1e-12) return;
        const mag = @sqrt(mag_sq);
        const inv_mag = 1.0 / mag;
        for (self.data) |*x| {
            x.* *= inv_mag;
        }
    }

    pub fn dotProduct(self: Vector, other: Vector) f32 {
        if (self.data.len != other.data.len) return 0;
        var sum: f32 = 0;
        const len = self.data.len;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            sum += self.data[i] * other.data[i];
        }
        return sum;
    }

    pub fn cosineSimilarity(self: Vector, other: Vector) f32 {
        const dot = self.dotProduct(other);
        return @max(-1.0, @min(1.0, dot));
    }
};

pub const VectorDatabase = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    indices: std.StringHashMap(*VectorIndex),

    pub fn init(allocator: std.mem.Allocator, cfg: config.Config) VectorDatabase {
        return VectorDatabase{
            .allocator = allocator,
            .cfg = cfg,
            .indices = std.StringHashMap(*VectorIndex).init(allocator),
        };
    }

    pub fn deinit(self: *VectorDatabase) void {
        var it = self.indices.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.*.deinit();
            self.allocator.destroy(entry.value_ptr.*);
        }
        self.indices.deinit();
    }

    pub fn getIndex(self: *VectorDatabase, name: []const u8) ?*VectorIndex {
        return self.indices.get(name);
    }

    pub fn createIndex(self: *VectorDatabase, name: []const u8) !*VectorIndex {
        const idx = try self.allocator.create(VectorIndex);
        idx.* = VectorIndex.init(self.allocator, self.cfg.vector_dimensions);
        try self.indices.put(name, idx);
        return idx;
    }
};

pub const SearchResult = struct {
    doc_id: u64,
    score: f32,
    metadata: []const u8,
    allocator: std.mem.Allocator,

    pub fn deinit(self: *SearchResult) void {
        if (self.metadata.len > 0) {
            self.allocator.free(self.metadata);
        }
    }
};

pub const VectorIndex = struct {
    allocator: std.mem.Allocator,
    dims: usize,
    vectors: std.ArrayList(Vector),
    ids: std.ArrayList(u64),
    metadata: std.ArrayList([]u8),
    lock: std.Thread.Mutex,

    pub fn init(allocator: std.mem.Allocator, dims: usize) VectorIndex {
        return VectorIndex{
            .allocator = allocator,
            .dims = dims,
            .vectors = std.ArrayList(Vector).init(allocator),
            .ids = std.ArrayList(u64).init(allocator),
            .metadata = std.ArrayList([]u8).init(allocator),
            .lock = .{},
        };
    }

    pub fn deinit(self: *VectorIndex) void {
        for (self.vectors.items) |*v| v.deinit();
        self.vectors.deinit();
        self.ids.deinit();
        for (self.metadata.items) |m| self.allocator.free(m);
        self.metadata.deinit();
    }

    pub fn add(self: *VectorIndex, id: u64, vec: *const Vector, meta: []const u8) !void {
        self.lock.lock();
        defer self.lock.unlock();

        var v_copy = try Vector.fromSlice(self.allocator, vec.data);
        errdefer v_copy.deinit();

        const meta_copy = try self.allocator.dupe(u8, meta);
        errdefer self.allocator.free(meta_copy);

        try self.vectors.append(v_copy);
        try self.ids.append(id);
        try self.metadata.append(meta_copy);
    }

    pub fn clusterSearch(self: *VectorIndex, query: *const Vector, k: usize, probes: usize) ![]SearchResult {
        _ = probes;
        self.lock.lock();
        defer self.lock.unlock();

        var scores = try self.allocator.alloc(SearchResult, self.vectors.items.len);
        var count: usize = 0;

        for (self.vectors.items, 0..) |vec, i| {
            const score = query.cosineSimilarity(vec);
            if (score > 0) {
                const meta = try self.allocator.dupe(u8, self.metadata.items[i]);
                scores[count] = SearchResult{
                    .doc_id = self.ids.items[i],
                    .score = score,
                    .metadata = meta,
                    .allocator = self.allocator,
                };
                count += 1;
            }
        }

        const valid_scores = scores[0..count];
        std.mem.sort(SearchResult, valid_scores, {}, compareScores);

        const result_k = @min(k, count);
        var results = try self.allocator.alloc(SearchResult, result_k);
        for (0..result_k) |i| {
            results[i] = valid_scores[i];
        }

        for (result_k..count) |i| {
            valid_scores[i].deinit();
        }

        self.allocator.free(scores);
        return results;
    }
};

fn compareScores(_: void, a: SearchResult, b: SearchResult) bool {
    return a.score > b.score;
}
