pub const IndexManager = struct {
    allocator: std.mem.Allocator,
    documents: std.ArrayList(Document),
    mutex: std.Thread.Mutex,

    pub fn init(allocator: std.mem.Allocator) IndexManager {
        return IndexManager{
            .allocator = allocator,
            .documents = std.ArrayList(Document).init(allocator),
            .mutex = .{},
        };
    }

    pub fn deinit(self: *IndexManager) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        for (self.documents.items) |*doc| {
            doc.deinit();
        }
        self.documents.deinit();
    }

    pub fn addDocument(self: *IndexManager, doc: Document) !u64 {
        self.mutex.lock();
        defer self.mutex.unlock();
        try self.documents.append(doc);
        return self.documents.items.len - 1;
    }

    pub fn getDocument(self: *IndexManager, id: u64) !Document {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (id >= self.documents.items.len) return error.DocumentNotFound;
        return self.documents.items[@intCast(id)].clone();
    }
