const std = @import("std");
const query = @import("query.zig");
const vector_db = @import("vector_db.zig");
const embeddings = @import("embeddings.zig");
const config = @import("config.zig");
const modal_client = @import("modal_client.zig");

pub const AutoSearchEngine = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    embedding_service: *embeddings.EmbeddingService,
    database: *vector_db.VectorDatabase,
    query_history: std.ArrayList(QueryHistoryEntry),
    modal: modal_client.ModalClient,
    mode_stats: ModeStats,
    processor_pool: QueryProcessorPool,

    pub fn init(
        allocator: std.mem.Allocator,
        cfg: config.Config,
        embedding_svc: *embeddings.EmbeddingService,
        db: *vector_db.VectorDatabase,
    ) AutoSearchEngine {
        return AutoSearchEngine{
            .allocator = allocator,
            .cfg = cfg,
            .embedding_service = embedding_svc,
            .database = db,
            .query_history = std.ArrayList(QueryHistoryEntry).init(allocator),
            .modal = modal_client.ModalClient.init(allocator),
            .mode_stats = ModeStats.init(),
            .processor_pool = QueryProcessorPool.init(allocator, cfg, embedding_svc, db),
        };
    }

    pub fn deinit(self: *AutoSearchEngine) void {
        for (self.query_history.items) |*entry| entry.deinit();
        self.query_history.deinit();
        self.modal.deinit();
        self.processor_pool.deinit();
    }

    pub fn search(self: *AutoSearchEngine, q: query.Query) !query.QueryResponse {
        const predicted_mode = self.predictBestMode(q.text);
        var modified_query = q;
        modified_query.query_type = predicted_mode;

        var processor = self.processor_pool.get();
        defer self.processor_pool.release(processor);

        const response = try processor.process(modified_query);

        if (self.query_history.items.len >= self.cfg.query_history_size) {
             var old = self.query_history.orderedRemove(0);
             old.deinit();
        }

        const text_copy = try self.allocator.dupe(u8, q.text);
        try self.query_history.append(QueryHistoryEntry{
            .query_text = text_copy,
            .predicted_mode = predicted_mode,
            .actual_mode = predicted_mode,
            .result_count = response.results.items.len,
            .latency_ms = response.query_time_ms,
            .user_satisfaction = 0.5,
            .allocator = self.allocator,
        });

        self.mode_stats.recordQuery(predicted_mode, response.latency_target_met);
        return response;
    }

    fn predictBestMode(self: *AutoSearchEngine, text: []const u8) query.QueryType {
        if (text.len == 0) return .fast;

        var word_count: usize = 0;
        var it = std.mem.tokenize(u8, text, " \t\n\r");
        while (it.next()) |_| {
            word_count += 1;
        }

        var fast_score: f32 = 0;
        var neural_score: f32 = 0;
        var deep_score: f32 = 0;

        if (word_count <= 2) {
            fast_score += self.cfg.weights_fast_score;
        } else if (word_count <= 5) {
            fast_score += 0.5;
            neural_score += 0.5;
        } else {
            neural_score += self.cfg.weights_neural_score;
            deep_score += 0.2;
        }

        if (std.mem.indexOf(u8, text, "?") != null) {
            neural_score += self.cfg.weights_question_boost;
            deep_score += self.cfg.weights_question_boost;
        }

        if (fast_score >= neural_score and fast_score >= deep_score) return .fast;
        if (neural_score >= deep_score) return .neural;
        return .deep;
    }

    pub fn updateFromFeedback(self: *AutoSearchEngine, feedback: UserFeedback) void {
        if (feedback.query_index >= self.query_history.items.len) return;
        var entry = &self.query_history.items[feedback.query_index];
        entry.user_satisfaction = if (feedback.helpful) 1.0 else 0.0;
        if (feedback.helpful) self.mode_stats.recordSuccess(feedback.mode);
    }
};

pub const ModeStats = struct {
    fast_total: u32 = 0,
    fast_success: u32 = 0,
    neural_total: u32 = 0,
    neural_success: u32 = 0,
    deep_total: u32 = 0,
    deep_success: u32 = 0,

    pub fn init() ModeStats {
        return std.mem.zeroes(ModeStats);
    }

    pub fn recordQuery(self: *ModeStats, mode: query.QueryType, success: bool) void {
        switch (mode) {
            .fast => {
                self.fast_total += 1;
                if (success) self.fast_success += 1;
            },
            .neural => {
                self.neural_total += 1;
                if (success) self.neural_success += 1;
            },
            .deep => {
                self.deep_total += 1;
                if (success) self.deep_success += 1;
            },
            else => {},
        }
    }

    pub fn recordSuccess(self: *ModeStats, mode: query.QueryType) void {
        self.recordQuery(mode, true);
    }
};

pub const QueryHistoryEntry = struct {
    query_text: []const u8,
    predicted_mode: query.QueryType,
    actual_mode: query.QueryType,
    result_count: usize,
    latency_ms: u64,
    user_satisfaction: f32,
    allocator: std.mem.Allocator,

    pub fn deinit(self: *QueryHistoryEntry) void {
        self.allocator.free(self.query_text);
    }
};

pub const UserFeedback = struct {
    query_index: usize,
    mode: query.QueryType,
    helpful: bool,
};

pub const QueryProcessorPool = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    embedding_service: *embeddings.EmbeddingService,
    database: *vector_db.VectorDatabase,

    pub fn init(allocator: std.mem.Allocator, cfg: config.Config, svc: *embeddings.EmbeddingService, db: *vector_db.VectorDatabase) QueryProcessorPool {
        return QueryProcessorPool{
            .allocator = allocator,
            .cfg = cfg,
            .embedding_service = svc,
            .database = db,
        };
    }

    pub fn deinit(self: *QueryProcessorPool) void {
        _ = self;
    }

    pub fn get(self: *QueryProcessorPool) query.QueryProcessor {
        return query.QueryProcessor.init(self.allocator, self.cfg, self.embedding_service, self.database);
    }

    pub fn release(self: *QueryProcessorPool, p: query.QueryProcessor) void {
        var mutable_p = p;
        mutable_p.deinit();
        _ = self;
    }
};
