const std = @import("std");
const query = @import("query.zig");
const vector_db = @import("vector_db.zig");
const embeddings = @import("embeddings.zig");
const config = @import("config.zig");
const index_mod = @import("index.zig");

pub const FastSearchEngine = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    embedding_service: *embeddings.EmbeddingService,
    database: *vector_db.VectorDatabase,
    index_manager: ?*index_mod.IndexManager,
    cache: QueryCache,

    pub fn init(
        allocator: std.mem.Allocator,
        cfg: config.Config,
        embedding_svc: *embeddings.EmbeddingService,
        db: *vector_db.VectorDatabase,
        idx_mgr: ?*index_mod.IndexManager,
    ) FastSearchEngine {
        return FastSearchEngine{
            .allocator = allocator,
            .cfg = cfg,
            .embedding_service = embedding_svc,
            .database = db,
            .index_manager = idx_mgr,
            .cache = QueryCache.init(allocator, cfg.query_cache_size),
        };
    }

    pub fn deinit(self: *FastSearchEngine) void {
        self.cache.deinit();
    }

    pub fn search(self: *FastSearchEngine, q: query.Query) !query.QueryResponse {
        const timer = try std.time.Timer.start();

        if (self.cache.get(q.text)) |cached| {
            var resp = try cached.clone();
            resp.cached = true;
            return resp;
        }

        var response = query.QueryResponse.init(self.allocator);
        errdefer response.deinit();
        response.search_type = .fast;

        const emb = try self.embedding_service.computeQueryEmbedding(q.text);
        defer self.allocator.free(emb);

        var q_vec = try vector_db.Vector.init(self.allocator, self.cfg.vector_dimensions);
        defer q_vec.deinit();
        @memcpy(q_vec.data, emb);
        q_vec.normalize();

        const idx = self.database.getIndex("documents") orelse return error.IndexNotFound;
        const results = try idx.clusterSearch(&q_vec, q.max_results, 1);
        defer {
            for (results) |*r| r.deinit();
            self.allocator.free(results);
        }

        for (results) |sr| {
            if (sr.score < self.cfg.relevance_threshold) continue;

            var res = query.QueryResult.init(self.allocator);
            res.id = sr.doc_id;
            res.score = sr.score;
            res.url = try self.allocator.dupe(u8, sr.metadata);

            if (self.index_manager) |mgr| {
                if (mgr.getDocument(sr.doc_id)) |doc| {
                    defer {
                        var d = doc; 
                        d.deinit();
                    }
                    res.title = try self.allocator.dupe(u8, doc.title);
                    const snip_len = @min(doc.content.len, self.cfg.snippet_max_length);
                    res.snippet = try self.allocator.dupe(u8, doc.content[0..snip_len]);
                } else |_| {}
            }
            try response.results.append(res);
        }

        response.query_time_ms = timer.read() / 1_000_000;
        try self.cache.put(q.text, &response);

        return response;
    }
};

pub const QueryCache = struct {
    allocator: std.mem.Allocator,
    entries: std.StringHashMap(query.QueryResponse),
    max_size: usize,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: std.mem.Allocator, max_size: usize) QueryCache {
        return QueryCache{
            .allocator = allocator,
            .entries = std.StringHashMap(query.QueryResponse).init(allocator),
            .max_size = max_size,
            .mutex = .{},
        };
    }

    pub fn deinit(self: *QueryCache) void {
        var it = self.entries.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.deinit();
        }
        self.entries.deinit();
    }

    pub fn get(self: *QueryCache, key: []const u8) ?query.QueryResponse {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.entries.get(key)) |v| {
            return v.clone() catch return null;
        }
        return null;
    }

    pub fn put(self: *QueryCache, key: []const u8, value: *const query.QueryResponse) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.entries.count() >= self.max_size) {
            return; 
        }

        const k_copy = try self.allocator.dupe(u8, key);
        errdefer self.allocator.free(k_copy);
        const v_copy = try value.clone();

        try self.entries.put(k_copy, v_copy);
    }
};
