const index_mod = @import("index.zig");

pub const NeuralSearchEngine = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    embedding_service: *embeddings.EmbeddingService,
    database: *vector_db.VectorDatabase,
    index_manager: ?*index_mod.IndexManager,
    modal: modal_client.ModalClient,

    pub fn init(
        allocator: std.mem.Allocator,
        cfg: config.Config,
        embedding_svc: *embeddings.EmbeddingService,
        db: *vector_db.VectorDatabase,
        idx_mgr: ?*index_mod.IndexManager,
    ) NeuralSearchEngine {
        return NeuralSearchEngine{
            .allocator = allocator,
            .cfg = cfg,
            .embedding_service = embedding_svc,
            .database = db,
            .index_manager = idx_mgr,
            .modal = modal_client.ModalClient.init(allocator),
        };
    }

    pub fn deinit(self: *NeuralSearchEngine) void {
        self.modal.deinit();
    }

    pub fn search(self: *NeuralSearchEngine, q: query.Query) !query.QueryResponse {
        var response = query.QueryResponse.init(self.allocator);
        errdefer response.deinit();
        response.search_type = .neural;

        const emb_res = try self.modal.embed(&[_][]const u8{q.text}, self.cfg.vector_dimensions);
        var res_mutable = emb_res; 
        defer res_mutable.deinit();

        if (emb_res.embeddings.len == 0) return error.EmbeddingFailed;

        var q_vec = try vector_db.Vector.init(self.allocator, self.cfg.vector_dimensions);
        defer q_vec.deinit();
        @memcpy(q_vec.data, emb_res.embeddings[0]);
        q_vec.normalize();

        const idx = self.database.getIndex("documents") orelse return error.IndexNotFound;
        const initial_k = q.max_results * self.cfg.neural_rerank_multiplier;

        const search_results = try idx.clusterSearch(&q_vec, initial_k, 5);
        defer {
             for (search_results) |*r| r.deinit();
             self.allocator.free(search_results);
        }

        var docs_for_rerank = std.ArrayList([]const u8).init(self.allocator);
        defer {
            for (docs_for_rerank.items) |d| self.allocator.free(d);
            docs_for_rerank.deinit();
        }

        for (search_results) |sr| {
            if (self.index_manager) |mgr| {
                if (mgr.getDocument(sr.doc_id)) |doc| {
                    defer { var d = doc; d.deinit(); }
                    const content_copy = try self.allocator.dupe(u8, doc.content);
                    try docs_for_rerank.append(content_copy);
                } else |_| {
                    const empty = try self.allocator.dupe(u8, "");
                    try docs_for_rerank.append(empty);
                }
            } else {
                const empty = try self.allocator.dupe(u8, "");
                try docs_for_rerank.append(empty);
            }
        }

        const rerank_res = try self.modal.rerank(q.text, docs_for_rerank.items, q.max_results);
        var rr_mutable = rerank_res;
        defer rr_mutable.deinit();

        for (rerank_res.scores) |s| {
            if (s.index >= search_results.len) continue;
            var sr = &search_results[s.index];
            if (s.score < self.cfg.relevance_threshold) continue;

            var result = query.QueryResult.init(self.allocator);
            result.id = sr.doc_id;
            result.score = s.score;
            result.url = try self.allocator.dupe(u8, sr.metadata);

            if (self.index_manager) |mgr| {
                if (mgr.getDocument(sr.doc_id)) |doc| {
                    defer { var d = doc; d.deinit(); }
                    result.title = try self.allocator.dupe(u8, doc.title);
                    const sl = @min(doc.content.len, self.cfg.snippet_max_length);
                    result.snippet = try self.allocator.dupe(u8, doc.content[0..sl]);
                } else |_| {}
            }
            try response.results.append(result);
        }

        return response;
    }
};
