const embeddings = @import("embeddings.zig");
const config = @import("config.zig");
const index_mod = @import("index.zig");
const ai_client = @import("ai_client.zig");

pub const DeepSearchEngine = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    embedding_service: *embeddings.EmbeddingService,
    database: *vector_db.VectorDatabase,
    index_manager: ?*index_mod.IndexManager,
    ai: ai_client.AiClient,

    pub fn init(
        allocator: std.mem.Allocator,
        cfg: config.Config,
        embedding_svc: *embeddings.EmbeddingService,
        db: *vector_db.VectorDatabase,
        idx_mgr: ?*index_mod.IndexManager,
    ) DeepSearchEngine {
        return DeepSearchEngine{
            .allocator = allocator,
            .cfg = cfg,
            .embedding_service = embedding_svc,
            .database = db,
            .index_manager = idx_mgr,
            .ai = ai_client.AiClient.init(allocator),
        };
    }

    pub fn deinit(self: *DeepSearchEngine) void {
        self.ai.deinit();
    }

    pub fn search(self: *DeepSearchEngine, q: query.Query) !query.QueryResponse {
        var response = query.QueryResponse.init(self.allocator);
        errdefer response.deinit();
        response.search_type = .deep;

        const expanded = try self.ai.expandQuery(q.text);
        defer {
            for (expanded) |e| self.allocator.free(e);
            self.allocator.free(expanded);
        }

        var aggregated = std.AutoHashMap(u64, f32).init(self.allocator);
        defer aggregated.deinit();

        for (expanded) |eq| {
            var sub_q = q;
            sub_q.text = eq;
            const emb = try self.embedding_service.computeQueryEmbedding(eq);
            defer self.allocator.free(emb);

            var vec = try vector_db.Vector.init(self.allocator, self.cfg.vector_dimensions);
            defer vec.deinit();
            @memcpy(vec.data, emb);
            vec.normalize();

            const idx = self.database.getIndex("documents") orelse continue;
            const res = idx.clusterSearch(&vec, 10, 1) catch continue;
            defer {
                for (res) |*r| r.deinit();
                self.allocator.free(res);
            }

            for (res) |r| {
                const v = aggregated.get(r.doc_id) orelse 0;
                try aggregated.put(r.doc_id, @max(v, r.score));
            }
        }

        var it = aggregated.iterator();
        while (it.next()) |entry| {
            var res = query.QueryResult.init(self.allocator);
            res.id = entry.key_ptr.*;
            res.score = entry.value_ptr.*;
            if (self.index_manager) |mgr| {
                if (mgr.getDocument(res.id)) |doc| {
                    defer { var d = doc; d.deinit(); }
                    res.title = try self.allocator.dupe(u8, doc.title);
                    res.snippet = try self.allocator.dupe(u8, doc.content[0..@min(doc.content.len, 200)]);
                    res.url = try self.allocator.dupe(u8, doc.url);
                } else |_| {
                    res.url = try self.allocator.dupe(u8, "unknown");
                }
            }
            try response.results.append(res);
        }

        return response;
    }
};
