const std = @import("std");
const auto = @import("search/auto.zig");
const fast = @import("search/fast.zig");
const neural = @import("search/neural.zig");
const deep = @import("search/deep.zig");
const config = @import("config.zig");
const vector_db = @import("vector_db.zig");
const embeddings = @import("embeddings.zig");
const index_mod = @import("index.zig");
const query = @import("query.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var cfg = config.Config.init();
    try cfg.getEnvOrDefault(allocator);

    var db = vector_db.VectorDatabase.init(allocator, cfg);
    defer db.deinit();
    _ = try db.createIndex("documents");

    var idx_mgr = index_mod.IndexManager.init(allocator);
    defer idx_mgr.deinit();

    var embed_svc = embeddings.EmbeddingService{ .allocator = allocator };

    var engine = auto.AutoSearchEngine.init(allocator, cfg, &embed_svc, &db);
    defer engine.deinit();

    const server = std.net.Address.parseIp4(cfg.server_host, cfg.server_port) catch unreachable;
    var listener = try std.net.Address.listen(server, .{ .reuse_address = true });
    defer listener.deinit();

    while (true) {
        if (listener.accept()) |conn| {
            var c = conn;
            c.stream.close();
        } else |err| {
            std.log.err("Accept failed: {}", .{err});
        }
    }
}
